def migrate_creator_to_attribution(apps, schema_editor):
    Dataset = apps.get_model("vitrina_datasets", "Dataset")
    Attribution = apps.get_model("vitrina_datasets", "Attribution")
    DatasetAttribution = apps.get_model("vitrina_datasets", "DatasetAttribution")

    creator_attribution = Attribution.objects.filter(name="creator").first()
    if not creator_attribution:
        return

    for dataset in Dataset.objects.filter(information_system_creator__isnull=False):
        DatasetAttribution.objects.create(
            dataset=dataset,
            attribution=creator_attribution,
            organization_id=dataset.information_system_creator_id,
        )


def migrate_publisher_to_m2m(apps, schema_editor):
    Dataset = apps.get_model("vitrina_datasets", "Dataset")
    for dataset in Dataset.objects.filter(information_system_publisher__isnull=False):
        dataset.information_system_publishers.add(dataset.information_system_publisher_id)


def reverse_migrate_publisher_to_m2m(apps, schema_editor):
    Dataset = apps.get_model("vitrina_datasets", "Dataset")
    for dataset in Dataset.objects.prefetch_related("information_system_publishers").all():
        publishers = dataset.information_system_publishers.all()
        if publishers.exists():
            dataset.information_system_publisher = publishers.first()
            dataset.save(update_fields=["information_system_publisher"])


def add_is_public_service_subclass(apps, schema_editor) -> None:
    DCATResourceSubclass = apps.get_model("vitrina_datasets", "DCATResourceSubclass")

    subclass, _ = DCATResourceSubclass.objects.get_or_create(
        name="is_public_service",
        defaults={"uri": "cpsv:PublicService"},
    )

    subclass.set_current_language("lt")
    subclass.title = "E. paslauga"
    subclass.description = (
        "Galimybė teikti viešosios paslaugos procesus, kuriuos sudaro viešojo administravimo institucijų "
        "vykdomi arba jų vardu vykdomi veiksmai piliečiams, įmonėms ar kitiems viešosios teisės subjektams."
    )
    subclass.save()

    subclass.set_current_language("en")
    subclass.title = "E-service"
    subclass.description = (
        "The capability to deliver public service processes, consisting of actions performed by public "
        "administration institutions or on their behalf for citizens, businesses, or other public entities."
    )
    subclass.save()


def create_produces_relation(apps, schema_editor):
    Relation = apps.get_model("vitrina_datasets", "Relation")

    relation, created = Relation.objects.get_or_create(name="produces")
    if created:
        relation.set_current_language("lt")
        relation.title = "Sukuria"
        relation.inversive_title = "Sukuriamas"
        relation.save()
        relation.set_current_language("en")
        relation.title = "Produces"
        relation.inversive_title = "Is produced by"
        relation.save()


def populate_contact_kinds(apps, schema_editor):
    Contact = apps.get_model("vitrina_datasets", "Contact")
    ContentType = apps.get_model("contenttypes", "ContentType")

    org_ct_ids = ContentType.objects.filter(model="organization").values_list("id", flat=True)
    user_ct_ids = ContentType.objects.filter(model="user").values_list("id", flat=True)

    Contact.objects.filter(content_type_id__in=org_ct_ids).update(kind="org")
    Contact.objects.filter(content_type_id__in=user_ct_ids).update(kind="individual")
    Contact.objects.filter(content_type__isnull=True).update(kind="unregistered")


def rename_service_subclass_title(apps, schema_editor):
    from vitrina.datasets.models import DCATResourceSubclass
    subclass = DCATResourceSubclass.objects.filter(name=DCATResourceSubclass.SERVICE).first()
    if subclass:
        subclass.set_current_language("lt")
        subclass.title = "Duomenų paslauga"
        subclass.save()


def create_relates_to_data_service_relation(apps, schema_editor):
    Relation = apps.get_model("vitrina_datasets", "Relation")

    relation, created = Relation.objects.get_or_create(
        name="relatesToDataService",
        defaults={"uri": "dcataplt:relatesToDataService"},
    )

    relation.set_current_language("lt")
    relation.title = "Susijusi duomenų paslauga"
    relation.inversive_title = "Susijusi informacinė sistema"
    relation.save()

    relation.set_current_language("en")
    relation.title = "Relates to data service"
    relation.inversive_title = "Related information system"
    relation.save()


